import { Checkbox } from "./checkbox";
import * as React from "react";

export default function App() {
  const [picked, setPicked] = React.useState(['mentions']);
  const [agreed, setAgreed] = React.useState(false);
  const all = ['mentions', 'approvals', 'summary'];
  return <div className="checkbox-example"><style>{`.checkbox-example{width:362px;max-width:100%;padding:20px;border:1px solid #e9e9e9;background:white;border-radius:12px;color:#222;font:13px/1.5 Inter,system-ui,sans-serif}.checkbox-example fieldset{padding:0;margin:0 0 20px;border:0}.checkbox-example legend{padding:0;margin-bottom:12px}.checkbox-example .checkbox-nested{display:grid;gap:12px;margin:14px 0 0 26px}.checkbox-example>div:last-child{margin-top:18px}:where(.dark,[data-theme=dark]) .checkbox-example{background:#131315;border-color:#29292b;color:#eee}`}</style><fieldset><legend>Email me about</legend><Checkbox label="Everything" checked={picked.length===3} indeterminate={picked.length>0 && picked.length<3} onChange={()=>setPicked(picked.length===3?[]:all)}/><div className="checkbox-nested">{[{id:'mentions',label:'Mentions',description:'Someone mentions you in a chat or a file'},{id:'approvals',label:'Approvals',description:'An agent waits for your OK before it acts'},{id:'summary',label:'Weekly summary'}].map(item=><Checkbox key={item.id} label={item.label} description={item.description} checked={picked.includes(item.id)} onChange={event=>setPicked(current=>event.target.checked?[...current,item.id]:current.filter(id=>id!==item.id))}/>)}</div></fieldset><Checkbox label="Keep a copy of every run" description="Inputs and outputs stay for 30 days, so you can replay a run." variant="card" defaultChecked/><div><Checkbox label="I agree to the terms of service" checked={agreed} onChange={event=>setAgreed(event.target.checked)} error={agreed?undefined:'Agree to the terms to continue.'}/></div></div>;
}

